{
  "name": "Anlotinib (multi-target TKI: VEGFR/FGFR/PDGFR/c-Kit)",
  "status": "Investigational for EMC; approved in China for some advanced soft-tissue sarcomas",
  "summary": "In a phase IIB soft-tissue sarcoma trial, anlotinib improved median progression-free survival vs placebo (6.27 vs 1.47 months). EMC-specific data are limited, but its anti-angiogenic mechanism is similar to pazopanib.",
  "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11443219/"
},
{
  "name": "Imatinib (KIT inhibitor) — only for KIT-mutant EMC",
  "status": "Off-label; single published case (biomarker-restricted)",
  "summary": "A small minority of EMCs carry an actionable KIT mutation. In one published patient with a KIT exon-11 mutation and lung metastases, imatinib gave 3 years of stable disease. This applies ONLY if molecular testing shows a KIT mutation — it is not a general EMC treatment, and is based on a single case. Discuss NGS testing and any such option with a sarcoma specialist, ideally in a trial.",
  "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8395296/"
},
{
  "name": "Sunitinib (multi-target TKI)",
  "status": "Off-label; small series / case reports in EMC",
  "summary": "Reported tumour responses in a subset of EMC patients, supporting the role of anti-angiogenic TKIs in this disease.",
  "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3534218/"
},
{
  "name": "Immune checkpoint inhibitors (e.g. nivolumab), alone or with a TKI",
  "status": "Experimental; case-level evidence",
  "summary": "Responses to immunotherapy in EMC have so far been occasional rather than reliable, and it is not standard treatment. What the tumour's immune environment looks like appears to vary between patients rather than being the same in everyone: one published EMC case describes an immunosuppressive environment, and another describes an immune-rich one with high PD-L1 that responded to pembrolizumab. Only a handful of EMC tumours have ever been profiled this way, so nobody knows how common either pattern is. Being studied in combination strategies.",
  "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9527174/"
},
